                Color c = cd.Color;                if (c.IsNamedColor) MessageBox.Show(c.Name);                if (c.IsKnownColor) { MessageBox.Show(c.ToKnownColor().ToString()); }                Color co = Color.MintCream;                MessageBox.Show(co.Name);                Color cr = Color.FromKnownColor(KnownColor.ActiveBorder);                MessageBox.Show(cr.ToKnownColor().ToString());                MessageBox.Show(cr.ToArgb().ToString("x"));                 Color cc = Color.Black;                int i = cc.ToArgb();                Color b = Color.FromArgb(i);                button1.BackColor = b;        private static string SerializeObject(object value, string valueTypeName) {            var str = String.Empty;            switch (valueTypeName) {                case "String": str = (string)value; break;                case "Color":                    // if color is known convert it in to RGB                    Color clr = value != null ? (Color)value : new Color();                    if (clr.IsKnownColor) value = Color.FromArgb(clr.ToArgb());                    str = JsonConvert.SerializeObject(value, Formatting.Indented);                    break;                default: str = JsonConvert.SerializeObject(value, Formatting.Indented); break;            }            return str;        }        public static string SerializeColor(Color color) {            if (color.IsNamedColor) return string.Format("{0}:{1}", ColorFormat.NamedColor, color.Name);            else return string.Format("{0}:{1}:{2}:{3}:{4}", ColorFormat.ARGBColor,                color.A, color.R, color.G, color.B);        }